function field(label, hint, inner) { return '<div style="display:flex;flex-direction:column;gap:6px"><div style="font-weight:550">' + label + '</div>' + (hint ? '<div style="font-size:12px;color:var(--mute)">' + hint + '</div>' : '') + inner + '</div>'; }
